import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十六卦 明夷 地火明夷 坤上離下","description":"周易 - 第三十六卦 明夷 地火明夷 坤上離下","frontmatter":{"title":"第三十六卦 明夷 地火明夷 坤上離下","description":"周易 - 第三十六卦 明夷 地火明夷 坤上離下"},"headers":[],"relativePath":"classics/zhouyi/037.md","filePath":"classics/zhouyi/037.md"}'),l={name:"classics/zhouyi/037.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="明夷" tabindex="-1">明夷 <a class="header-anchor" href="#明夷" aria-label="Permalink to “明夷”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利艱貞。 彖曰：明入地中，明夷。內文明而外柔順，以蒙大難，文王以之。利艱貞，晦其明也，內難而能正其志，箕子以之。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>明入地中，明夷；君子以蒞眾，用晦而明。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>明夷于飛，垂其翼。君子於 行，三日不食，有攸往，主人有言。象曰：君子於行，義不食也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>明夷，夷於左股，用拯馬壯，吉。象曰：六二之吉，順以則也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>明夷於南狩，得其大首，不可疾貞。象曰：南狩之志，乃大得也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>入於左腹，獲明夷之心，出於門庭。象曰：入於左腹，獲心意也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>箕子之明夷，利貞。象曰：箕子之貞，明不可息也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>不明晦，初登於天，後入於地。象曰：初登於天，照四國也。後入於地，失則也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
